    explanation: '4M分析は人・機械・材料・方法の4つの観点から多面的に原因を検討する手法であり、原因を人の不注意のみに帰結させるものではない。\n【図解】4M分析\n　Man（人）・Machine（機械）・Material（材料）★\n　Method（方法）の4観点で多面的に分析★\n　特性要因図の大骨として活用されることも★\n　×原因を人（不注意）のみに帰結（誤り）',
    difficulty: 'standard',
