    correctKey: 'A',
    explanation: '管理図の異常判定は、管理限界線からの逸脱だけでなく、連・トレンド・周期性等、限界線内の点の並び方のパターンも考慮することが、工程の変化を早期に把握するうえで重要である。\n【図解】管理図の異常判定ルール\n　①管理限界線（UCL/LCL）外の点★\n　②連（ラン）：中心線片側に連続（目安7点等）★\n　③トレンド：一定方向への連続的な上昇・下降★\n　×限界線外のみで判定（誤り。パターンも考慮）',
    difficulty: 'advanced',
